<?php
$adminPage='customers';$adminTitle='Customer review';$adminPermission='customers.view';require __DIR__.'/../includes/admin_header.php';$id=(int)($_GET['id']??$_POST['id']??0);$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();$action=$_POST['action']??'';if($action==='kyc'){requirePermission('kyc.manage');$state=$_POST['kyc_status']??'';if(!in_array($state,['under_review','verified','rejected','needs_information','expired'],true))throw new InvalidArgumentException('Invalid KYC state.');$pdo->beginTransaction();$pdo->prepare("UPDATE users SET kyc_status=? WHERE user_id=? AND role='customer'")->execute([$state,$id]);$pdo->prepare("UPDATE id_verifications SET verification_status=?,verified_at=IF(?='verified',NOW(),NULL) WHERE user_id=?")->execute([in_array($state,['verified','rejected'],true)?$state:'pending',$state,$id]);audit($pdo,'kyc.status_changed','user',$id,['status'=>$state,'reason'=>substr(trim($_POST['reason']??''),0,500)]);$pdo->commit();$notice='KYC decision recorded.';}elseif($action==='access'){requirePermission('customers.manage');$active=(int)($_POST['active']??0);$pdo->prepare("UPDATE users SET is_active=?,session_version=session_version+1 WHERE user_id=? AND role='customer'")->execute([$active,$id]);audit($pdo,$active?'customer.reactivated':'customer.restricted','user',$id,['reason'=>substr(trim($_POST['reason']??''),0,500)]);$notice='Customer access updated.';}elseif($action==='note'){requirePermission('customers.manage');$note=trim($_POST['note']??'');if(strlen($note)<3)throw new InvalidArgumentException('Enter a meaningful internal note.');$pdo->prepare('INSERT INTO admin_customer_notes(customer_user_id,actor_user_id,note) VALUES(?,?,?)')->execute([$id,$_SESSION['user_id'],substr($note,0,2000)]);audit($pdo,'customer.note_added','user',$id);$notice='Internal note added.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$stmt=$pdo->prepare("SELECT u.*,a.account_number,a.balance_cents,iv.id_type,iv.id_file_path,iv.verification_status FROM users u LEFT JOIN accounts a ON a.user_id=u.user_id LEFT JOIN id_verifications iv ON iv.user_id=u.user_id WHERE u.user_id=? AND u.role='customer'");$stmt->execute([$id]);$customer=$stmt->fetch();if(!$customer){http_response_code(404);exit('Customer not found.');}$cards=$pdo->prepare('SELECT network,last_four,verification_status,status,created_at FROM linked_cards WHERE user_id=? ORDER BY created_at DESC');$cards->execute([$id]);$cardRows=$cards->fetchAll();$transactions=$pdo->prepare('SELECT reference,type,amount_cents,fee_cents,status,created_at FROM financial_transactions WHERE user_id=? ORDER BY created_at DESC LIMIT 10');$transactions->execute([$id]);$notes=$pdo->prepare('SELECT n.*,u.full_name actor FROM admin_customer_notes n JOIN users u ON u.user_id=n.actor_user_id WHERE customer_user_id=? ORDER BY created_at DESC');$notes->execute([$id]);
?>
<div class="actions"><a href="customers.php">← Customer queue</a></div><?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><section class="panel"><div class="admin-section-head"><div><h2><?=e($customer['full_name'])?></h2><p class="muted"><?=e($customer['email'])?> · <?=e($customer['account_number']??'No account')?></p></div><span class="badge <?=e($customer['kyc_status'])?>"><?=e(str_replace('_',' ',$customer['kyc_status']))?></span></div><div class="detail-grid"><div><span>Available balance</span><strong><?=Money::format((int)($customer['balance_cents']??0))?></strong></div><div><span>Phone</span><strong><?=e($customer['phone'])?></strong></div><div><span>Access</span><strong><?=$customer['is_active']?'Active':'Restricted'?></strong></div><div><span>Joined</span><strong><?=e(formatDate($customer['created_at']))?></strong></div><div><span>ID type</span><strong><?=e($customer['id_type']??'Not submitted')?></strong></div><div><span>Document</span><strong><?php if(!empty($customer['id_file_path'])):?><a href="document.php?id=<?=$id?>" target="_blank">Open safely</a><?php else:?>None<?php endif?></strong></div></div></section><div class="app-grid"><section class="panel span-6"><h2>KYC decision</h2><?php if(can('kyc.manage')):?><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="kyc"><div class="field"><label>Status</label><select name="kyc_status" required><?php foreach(['under_review','verified','rejected','needs_information','expired'] as $s):?><option value="<?=e($s)?>"><?=e(str_replace('_',' ',$s))?></option><?php endforeach?></select></div><div class="field full"><label>Decision reason</label><textarea name="reason" maxlength="500" required></textarea></div><button class="button button-primary">Record KYC decision</button></form><?php else:?><p class="muted">Your role has read-only KYC access.</p><?php endif?></section><section class="panel span-6"><h2>Account access</h2><?php if(can('customers.manage')):?><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="access"><input type="hidden" name="active" value="<?=$customer['is_active']?0:1?>"><div class="field full"><label>Reason</label><textarea name="reason" maxlength="500" required></textarea></div><button class="button <?=$customer['is_active']?'button-danger':'button-primary'?>"><?=$customer['is_active']?'Restrict access':'Reactivate customer'?></button></form><?php else:?><p class="muted">Your role cannot change customer access.</p><?php endif?></section><section class="panel span-5"><h2>Linked cards</h2><?php foreach($cardRows as $card):?><div class="note"><strong><?=e(strtoupper($card['network']))?> •••• <?=e($card['last_four'])?></strong><br><span class="muted"><?=e($card['verification_status'])?> · <?=e($card['status'])?></span></div><?php endforeach;if(!$cardRows):?><div class="empty">No linked cards.</div><?php endif?></section><section class="panel span-7"><h2>Recent transactions</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Type</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($transactions as $tx):?><tr><td class="mono"><?=e($tx['reference'])?></td><td><?=e($tx['type'])?></td><td><?=Money::format((int)$tx['amount_cents'])?></td><td><span class="badge <?=e($tx['status'])?>"><?=e($tx['status'])?></span></td></tr><?php endforeach?></tbody></table></div></section><section class="panel span-12"><h2>Internal notes</h2><?php if(can('customers.manage')):?><form method="post" class="compact-form"><?=csrfField()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="note"><input name="note" maxlength="2000" required placeholder="Visible only to authorized operations staff"><button class="button button-secondary">Add note</button></form><?php endif?><?php foreach($notes as $note):?><div class="note"><strong><?=e($note['actor'])?></strong> <small><?=e(formatDate($note['created_at']))?></small><p><?=nl2br(e($note['note']))?></p></div><?php endforeach?></section></div><?php require __DIR__.'/../includes/admin_footer.php';?>
